"use client";

import { useState } from "react";
import "./cadastro.css";

interface CadastroForm {
  nomeCompleto: string;
  username: string;
  email: string;
  senha: string;
  confirmarSenha: string;
}

function EyeIcon({ aberto }: { aberto: boolean }) {
  return (
    <svg width="22" height="3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true">
      <path d="M1.5 12s3.8-7 10.5-7 10.5 7 10.5 7-3.8 7-10.5 7S1.5 12 1.5 12Z" />
      <circle cx="12" cy="12" r="3" />
      {!aberto && <path d="M3 3l18 18" />}
    </svg>
  );
}

export default function Cadastro() {
  const [form, setForm] = useState<CadastroForm>({
    nomeCompleto: "",
    username: "",
    email: "",
    senha: "",
    confirmarSenha: "",
  });
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [mostrarConfirmar, setMostrarConfirmar] = useState(false);
  const [erro, setErro] = useState("");
  const [enviando, setEnviando] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setErro("");
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (form.senha !== form.confirmarSenha) {
      setErro("As senhas não coincidem.");
      return;
    }

    setEnviando(true);
    try {
      // Troque pela URL do seu backend NestJS
      const resposta = await fetch("http://localhost:3000/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          nomeCompleto: form.nomeCompleto,
          username: form.username,
          email: form.email,
          senha: form.senha,
        }),
      });

      if (!resposta.ok) {
        throw new Error("Não foi possível criar a conta. Tente novamente.");
      }
      // redirecionar para o login aqui
    } catch (err) {
      setErro(err instanceof Error ? err.message : "Erro inesperado.");
    } finally {
      setEnviando(false);
    }
  };

  return (
    <main className="cadastro">
      <section className="cadastro__card">
        <h1 className="cadastro__titulo">Crie sua conta</h1>

        <form className="cadastro__form" onSubmit={handleSubmit}>
          <input className="campo" name="nomeCompleto" placeholder="Nome Completo" autoComplete="name"
            value={form.nomeCompleto} onChange={handleChange} required />

          <input className="campo" name="username" placeholder="Username" autoComplete="username"
            value={form.username} onChange={handleChange} required />

          <input className="campo" name="email" type="email" placeholder="Email" autoComplete="email"
            value={form.email} onChange={handleChange} required />

          <div className="campo-senha">
            <input className="campo" name="senha" placeholder="Senha" autoComplete="new-password"
              type={mostrarSenha ? "text" : "password"}
              value={form.senha} onChange={handleChange} required minLength={6} />
            <button type="button" className="campo-senha__olho"
              onClick={() => setMostrarSenha(!mostrarSenha)}
              aria-label={mostrarSenha ? "Ocultar senha" : "Mostrar senha"}>
              <EyeIcon aberto={mostrarSenha} />
            </button>
          </div>

          <div className="campo-senha">
            <input className="campo" name="confirmarSenha" placeholder="Confirmar Senha" autoComplete="new-password"
              type={mostrarConfirmar ? "text" : "password"}
              value={form.confirmarSenha} onChange={handleChange} required />
            <button type="button" className="campo-senha__olho"
              onClick={() => setMostrarConfirmar(!mostrarConfirmar)}
              aria-label={mostrarConfirmar ? "Ocultar senha" : "Mostrar senha"}>
              <EyeIcon aberto={mostrarConfirmar} />
            </button>
          </div>

          {erro && <p className="cadastro__erro" role="alert">{erro}</p>}

          <button type="submit" className="cadastro__botao" disabled={enviando}>
            {enviando ? "Criando..." : "Criar conta"}
          </button>
        </form>

        <p className="cadastro__login">
          Já possui uma conta? <a href="/login">Login</a>
        </p>
      </section>

      <aside className="cadastro__lado">
        <img className="cadastro__logo" src="/logo-stockio.png" alt="Stock.io" />
<img className="cadastro__personagem" src="/stocklee.svg" alt="" />
      </aside>
    </main>
  );
}
